CREATE PROCEDURE [monitoring].[InsertDailyOperationalReport]
	(

	@BranchId INT,
	@EndDate BIGINT
	)
	AS 
	BEGIN
	/*----------EXEC: StartDate Tracking---------
	DECLARE @StartExecDate	DATETIME;
	DECLARE @EndExecDate	DATETIME;
	DECLARE @ExecTime		VARCHAR(255);
	DECLARE @ProcName		VARCHAR(255)	= 'InsertDailyOperationalReport';
	DECLARE @vBranchId		INT				= @BranchId;
	DECLARE @LoId			INT				= null;
	DECLARE @Remarks		VARCHAR(MAX)	= null;
	DECLARE @ParameterList	VARCHAR(MAX)	= 'exec [monitoring].[InsertDailyOperationalReport]  @BranchId='+CAST(@BranchId AS VARCHAR)+', @EndDate='+CAST(@EndDate AS VARCHAR);
	SET @StartExecDate=GETDATE(); 
	PRINT '@StartExecDate = '+CONVERT(VARCHAR,@StartExecDate,9);
	--------------------------------------*/

	--EXEC [monitoring].[InsertDailyOperationalReport] 560,20260405000000
	--select *FROM [monitoring].[DailyOperationalReport]
	--DECLARE @BranchId INT, @EndDate BIGINT
	--SET @BranchId  = 2008
	--SET @EndDate  = 20250605000000
	DECLARE @PreviousDate BIGINT = [migration].[Func_GetDateTimeToBigint](DATEADD(day, -1, [migration].[Func_GetBigintToDate](@EndDate)))
